<h1 class="h3"><?= $row?'Edit':'Tambah' ?> <?= $kind==='products'?'produk':'kategori' ?></h1><form class="card p-4" method="post" enctype="multipart/form-data" action="<?= site_url('admin/'.$kind.(isset($row['id'])?'/'.$row['id']:'')) ?>"><?= csrf_field() ?><?php foreach (['name'=>'Nama','slug'=>'Slug (huruf kecil, angka, tanda hubung)','description'=>'Deskripsi'] as $key=>$label): ?><label for="<?= $key ?>"><?= $label ?></label><?php if ($key==='description'): ?><textarea class="form-control mb-3" id="<?= $key ?>" name="<?= $key ?>"><?= esc(old($key,$row[$key]??'')) ?></textarea><?php else: ?><input class="form-control mb-3" id="<?= $key ?>" name="<?= $key ?>" required maxlength="255" value="<?= esc(old($key,$row[$key]??'')) ?>"><?php endif ?><?php endforeach ?>
<?php if ($kind==='products'): ?><label for="category_id">Kategori</label><select class="form-select mb-3" id="category_id" name="category_id" required><?php foreach ($categories as $c): ?><option value="<?= $c['id'] ?>" <?= old('category_id',$row['category_id']??'')==$c['id']?'selected':'' ?>><?= esc($c['name']) ?></option><?php endforeach ?></select><?php foreach (['price'=>'Harga','stock'=>'Stok'] as $key=>$label): ?><label for="<?= $key ?>"><?= $label ?></label><input class="form-control mb-3" type="number" min="0" step="<?= $key==='price'?'0.01':'1' ?>" name="<?= $key ?>" id="<?= $key ?>" value="<?= esc(old($key,$row[$key]??0)) ?>" required><?php endforeach ?><label for="status">Status</label><select class="form-select mb-3" name="status" id="status"><?php foreach (['active','inactive'] as $status): ?><option <?= old('status',$row['status']??'active')===$status?'selected':'' ?>><?= $status ?></option><?php endforeach ?></select><label for="image">Gambar JPEG/PNG, maksimal 2 MB</label><input class="form-control mb-3" type="file" id="image" name="image" accept="image/jpeg,image/png"><?php else: ?><label for="is_active">Status kategori</label><select class="form-select mb-3" id="is_active" name="is_active"><option value="1">Aktif</option><option value="0" <?= old('is_active',$row['is_active']??1)==0?'selected':'' ?>>Nonaktif</option></select><?php endif ?><button class="btn btn-primary align-self-start">Simpan</button></form>
